impl super::RequestHandler for CodeActionResolve {
    type RequestType = req::CodeActionResolveRequest;
}

impl super::BackgroundDocumentRequestHandler for CodeActionResolve {
    fn document_url(params: &types::CodeAction) -> Cow<'_, types::Url> {
        let uri: lsp_types::Url = serde_json::from_value(params.data.clone().unwrap_or_default())
            .expect("code actions should have a URI in their data fields");
        Cow::Owned(uri)
    }
    fn run_with_snapshot(
        snapshot: DocumentSnapshot,
        _client: &Client,
        mut action: types::CodeAction,
    ) -> Result<types::CodeAction> {
```

It maps the action kind to a `SupportedCodeAction` (lines 36-52) and fills `action.edit` for `SourceFixAll` / `SourceOrganizeImports` (lines 69-92), returning `QuickFix` actions unchanged (lines 87-91). Helper edit builders `resolve_edit_for_fix_all` / `resolve_edit_for_organize_imports` are at lines 98-138.

## 2. Hover

**`ruff_server`** — `/workspace/repo/crates/ruff_server/src/server/api/requests/hover.rs`
- Struct `Hover` → `req::HoverRequest`, lines **12-16**; `run_with_snapshot` at **lines 22-29** delegates to the free `hover()` fn (**lines 31-89**). Notable: this server's hover only reports rule info for `# noqa` codes under the cursor (regex-based, lines 58-78), not general symbol info.

```rust
