44	/// Processes a request from the client to the server.
45	///
46	/// The LSP specification requires that each request has exactly one response. Therefore,
47	/// it's crucial that all paths in this method call [`Client::respond`] exactly once.
48	/// The only exception to this is requests that were cancelled by the client. In this case,
49	/// the response was already sent by the [`notification::CancelNotificationHandler`].
50	pub(super) fn request(req: server::Request) -> Task {
51	    let id = req.id.clone();
52	
53	    match req.method.as_str() {
54	        request::CodeActions::METHOD => {
55	            background_request_task::<request::CodeActions>(req, BackgroundSchedule::Worker)
56	        }
57	        request::CodeActionResolve::METHOD => {
58	            background_request_task::<request::CodeActionResolve>(req, BackgroundSchedule::Worker)
59	        }
60	        request::DocumentDiagnostic::METHOD => {
61	            background_request_task::<request::DocumentDiagnostic>(req, BackgroundSchedule::Worker)
62	        }
63	        request::ExecuteCommand::METHOD => sync_request_task::<request::ExecuteCommand>(req),
64	        request::Format::METHOD => {
65	            background_request_task::<request::Format>(req, BackgroundSchedule::Fmt)
66	        }
67	        request::FormatRange::METHOD => {
68	            background_request_task::<request::FormatRange>(req, BackgroundSchedule::Fmt)
69	        }
70	        request::Hover::METHOD => {
71	            background_request_task::<request::Hover>(req, BackgroundSchedule::Worker)
72	        }
73	        lsp_types::request::Shutdown::METHOD => sync_request_task::<requests::ShutdownHandler>(req),
74	        method => {
75	            tracing::warn!("Received request {method} which does not have a handler");
76	            let result: Result<()> = Err(Error::new(
77	                anyhow!("Unknown request: {method}"),
78	                server::ErrorCode::MethodNotFound,
79	            ));
80	            return Task::immediate(id, result);
81	        }
82	    }
83	    .unwrap_or_else(|err| {
84	        tracing::error!("Encountered error when routing request with ID {id}: {err}");
85	
86	        Task::sync(move |_session, client| {
87	            client.show_error_message(
88	                "Ruff failed to handle a request from the editor. Check the logs for more details.",
89	            );
90	            respond_silent_error(
91	                id,
92	                client,
93	                lsp_server::ResponseError {
94	                    code: err.code as i32,
95	                    message: err.to_string(),
96	                    data: None,
97	                },
98	            );
99	        })
100	    })
101	}
